import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const canvas=$('#world');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.18;
const scene=new THREE.Scene(); scene.background=new THREE.Color('#d68c9e'); scene.fog=new THREE.FogExp2('#c987a0',.0065);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,450); camera.position.set(0,5.5,10);
scene.add(new THREE.HemisphereLight('#ffe4d0','#384668',2.1));
const sunLight=new THREE.DirectionalLight('#ffd4a2',3.3); sunLight.position.set(-12,22,10); sunLight.castShadow=true; sunLight.shadow.mapSize.set(1024,1024); sunLight.shadow.camera.left=-28;sunLight.shadow.camera.right=28;sunLight.shadow.camera.top=30;sunLight.shadow.camera.bottom=-24; scene.add(sunLight);
const fill=new THREE.DirectionalLight('#c3a5ff',.7);fill.position.set(18,9,-35);scene.add(fill);
const mat=(color,roughness=.55,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const mats={road:mat('#323747',.32,.22),line:mat('#fff0cb',.44),grass:mat('#556b5c'),chrome:mat('#c5d0d5',.2,.82),rubber:mat('#171a22',.85),glass:mat('#243b50',.2,.3),lamp: new THREE.MeshStandardMaterial({color:'#fff1be',emissive:'#ffdb8d',emissiveIntensity:2}),redlamp:new THREE.MeshStandardMaterial({color:'#ff5149',emissive:'#ff251f',emissiveIntensity:1.6})};
const ground=new THREE.Mesh(new THREE.PlaneGeometry(800,600),mat('#6a805e'));ground.rotation.x=-Math.PI/2;ground.position.set(0,-.13,-120);ground.receiveShadow=true;scene.add(ground);
const sun=new THREE.Mesh(new THREE.SphereGeometry(10,32,24),new THREE.MeshBasicMaterial({color:'#ffc17e'}));sun.position.set(0,37,-155);scene.add(sun);
const halo=new THREE.Mesh(new THREE.TorusGeometry(15,.23,8,96),new THREE.MeshBasicMaterial({color:'#ffd5a1',transparent:true,opacity:.46}));halo.position.copy(sun.position);halo.rotation.x=.18;scene.add(halo);
const halo2=new THREE.Mesh(new THREE.TorusGeometry(18,.09,6,96),new THREE.MeshBasicMaterial({color:'#ffb6bd',transparent:true,opacity:.38}));halo2.position.copy(sun.position);halo2.rotation.x=.18;scene.add(halo2);
for(let i=0;i<7;i++){const hill=new THREE.Mesh(new THREE.SphereGeometry(1,28,16),mat(['#756c8e','#5f6b82','#526975'][i%3]));hill.scale.set(35+Math.random()*30,10+Math.random()*12,13);hill.position.set((i-3)*34-8,2,-116-Math.random()*12);scene.add(hill)}

const roadChunks=[];const chunkLength=32;
for(let i=0;i<9;i++){const g=new THREE.Group();const slab=new THREE.Mesh(new THREE.BoxGeometry(12,.18,chunkLength),mats.road);slab.receiveShadow=true;g.add(slab);for(const x of [-2,2]){const strip=new THREE.Mesh(new THREE.BoxGeometry(.12,.025,chunkLength),mat('#e5d6bd',.65));strip.position.set(x,.104,0);g.add(strip)}for(const x of [-5.65,5.65]){const edge=new THREE.Mesh(new THREE.BoxGeometry(.25,.28,chunkLength),mat('#d88373'));edge.position.set(x,.04,0);g.add(edge)}scene.add(g);roadChunks.push(g)}
const dashes=[];for(let i=0;i<36;i++){const d=new THREE.Mesh(new THREE.BoxGeometry(.14,.035,3.8),mats.line);d.position.y=.12;scene.add(d);dashes.push(d)}
const roadside=[];const treeMaterials=['#315b53','#3b6b5b','#47785e','#5b795c','#6a765f'].map(c=>mat(c));const trunkMat=mat('#594a4c');
function makeTree(){const g=new THREE.Group();const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13,.21,1.7,7),trunkMat);trunk.position.y=.85;g.add(trunk);for(let i=0;i<3;i++){const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(1.05-i*.13,1),treeMaterials[Math.floor(Math.random()*treeMaterials.length)]);crown.position.set((Math.random()-.5)*.24,1.8+i*.55,(Math.random()-.5)*.2);crown.scale.set(1.05-i*.1,1.05+i*.02,1);crown.castShadow=true;g.add(crown)}g.userData.bob=Math.random()*6.28;return g}
function makeBush(){const g=new THREE.Group();for(let i=0;i<4;i++){const b=new THREE.Mesh(new THREE.IcosahedronGeometry(.48,1),treeMaterials[Math.floor(Math.random()*treeMaterials.length)]);b.position.set((i-1.5)*.43,.34+Math.random()*.15,(Math.random()-.5)*.35);b.scale.set(1.2,.75,1);g.add(b)}g.userData.bob=Math.random()*6;return g}
for(let i=0;i<60;i++){let obj=Math.random()<.76?makeTree():makeBush();obj.position.set((Math.random()<.5?-1:1)*(9+Math.random()*20),0,-Math.random()*260);obj.scale.setScalar(.7+Math.random()*.8);scene.add(obj);roadside.push(obj)}
function makeHouse(){const g=new THREE.Group();let body=new THREE.Mesh(new THREE.BoxGeometry(4,2.4,3.3),mat('#e6c6a5'));body.position.y=1.2;g.add(body);let roof=new THREE.Mesh(new THREE.ConeGeometry(3.2,1.7,4),mat('#8b5452'));roof.rotation.y=Math.PI/4;roof.position.y=3.15;roof.scale.set(1,.7,.8);g.add(roof);const door=new THREE.Mesh(new THREE.BoxGeometry(.65,1.35,.08),mat('#745253'));door.position.set(0,.68,1.69);g.add(door);g.position.set(Math.random()<.5?-1:1,0,-80-Math.random()*120);scene.add(g);return g}
const houses=Array.from({length:5},makeHouse);

const paintColors=['#ed765d','#e9bd73','#53999a','#5d71b9','#d5d9d7','#9c5b87','#78a76e','#d1a342','#34394d','#f2a0a4','#7bb7c4','#9d7356'];
const cars=[{name:'RANGER PICKUP',type:'truck',handling:1.0},{name:'SUNSPRINT COUPE',type:'car',handling:1.16}];
let selected=0,paintIndex=[0,3],finish='gloss',wheelStyle='sport',skin='none';
const playerRoot=new THREE.Group();scene.add(playerRoot);let playerModel;const wheelMeshes=[];
function roundedBox(parent,w,h,d,color,rough=.3,metal=.12,pos=[0,0,0],scale=[1,1,1]){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(color,rough,metal));m.position.set(...pos);m.scale.set(...scale);m.castShadow=true;parent.add(m);return m}
function buildCar(type,color,decorate=true){const root=new THREE.Group();const paint=new THREE.MeshStandardMaterial({color,roughness:finish==='metallic'?.18:.28,metalness:finish==='metallic'?.82:.35,envMapIntensity:1.8});root.userData.paint=paint;
 if(type==='truck'){
  const base=new THREE.Mesh(new THREE.BoxGeometry(2.15,.72,3.55),paint);base.position.y=.72;base.castShadow=true;root.add(base);
  roundedBox(root,2.22,.13,1.05,'#20242c',.4,.1,[0,.47,-.91]);
  const cabin=new THREE.Mesh(new THREE.BoxGeometry(1.83,.9,1.55),paint);cabin.position.set(0,1.42,.39);cabin.castShadow=true;root.add(cabin);
  roundedBox(root,1.65,.1,1.2,'#191e29',.3,.15,[0,1.91,.37]);
  roundedBox(root,1.58,.59,.07,'#345163',.2,.38,[0,1.45,1.18],[1,1,1]);
  roundedBox(root,1.48,.57,.07,'#263f52',.22,.35,[0,1.44,-.39]);
  roundedBox(root,.09,.65,1.18,'#111923',.4,.12,[-.93,1.45,.39]);roundedBox(root,.09,.65,1.18,'#111923',.4,.12,[.93,1.45,.39]);
 }else{
  const body=new THREE.Mesh(new THREE.BoxGeometry(2.05,.72,3.38),paint);body.position.y=.7;body.scale.set(1,1,1);body.castShadow=true;root.add(body);
  const hood=new THREE.Mesh(new THREE.SphereGeometry(1,24,16),paint);hood.position.set(0,.91,.75);hood.scale.set(1.01,.36,.95);root.add(hood);
  const cabin=new THREE.Mesh(new THREE.SphereGeometry(1,24,16),paint);cabin.position.set(0,1.35,-.12);cabin.scale.set(.79,.62,.94);root.add(cabin);
  const wind=new THREE.Mesh(new THREE.BoxGeometry(1.35,.48,.07),mats.glass);wind.position.set(0,1.5,.57);wind.rotation.x=-.24;root.add(wind);
  const rearwin=new THREE.Mesh(new THREE.BoxGeometry(1.32,.43,.06),mats.glass);rearwin.position.set(0,1.49,-.77);rearwin.rotation.x=.25;root.add(rearwin);
  roundedBox(root,.07,.45,1.16,'#111923',.4,.1,[-.95,1.32,-.1]);roundedBox(root,.07,.45,1.16,'#111923',.4,.1,[.95,1.32,-.1]);
 }
 // chrome bumpers, lamps, grille and wheels
 roundedBox(root,2.28,.19,.2,'#bbc7ca',.18,.88,[0,.54,1.79]);roundedBox(root,2.2,.17,.18,'#abb7be',.2,.8,[0,.53,-1.82]);
 roundedBox(root,.56,.27,.055,'#282d38',.35,.1,[0,.77,1.79]);
 for(const x of [-.77,.77]){const lamp=new THREE.Mesh(new THREE.BoxGeometry(.42,.24,.1),mats.lamp);lamp.position.set(x,.94,1.79);root.add(lamp);const tail=new THREE.Mesh(new THREE.BoxGeometry(.34,.24,.08),mats.redlamp);tail.position.set(x,.83,-1.79);root.add(tail);const wheel=new THREE.Group();wheel.position.set(x,.48,.95);const tire=new THREE.Mesh(new THREE.CylinderGeometry(.43,.43,.3,18),mats.rubber);tire.rotation.z=Math.PI/2;tire.castShadow=true;wheel.add(tire);const rim=new THREE.Mesh(new THREE.CylinderGeometry(.24,.24,.315,12),mat('#aeb8bf',.22,.8));rim.rotation.z=Math.PI/2;wheel.add(rim);for(let k=0;k<5;k++){const spoke=new THREE.Mesh(new THREE.BoxGeometry(.045,.36,.035),mat('#e0e6e5',.2,.8));spoke.rotation.z=k*Math.PI/5;wheel.add(spoke)}root.add(wheel);wheelMeshes.push(wheel);const rear=wheel.clone();rear.position.z=-1.05;root.add(rear);wheelMeshes.push(rear)}
 root.userData.wheels=wheelMeshes.slice(-4);root.userData.type=type;return root}
function rebuildPlayer(){if(playerModel)playerRoot.remove(playerModel);wheelMeshes.length=0;playerModel=buildCar(cars[selected].type,paintColors[paintIndex[selected]]);playerModel.scale.setScalar(selected===0?1:1.01);playerRoot.add(playerModel);playerRoot.position.set(0,0,0)}
rebuildPlayer();
const traffic=[];const trafficColors=['#e78a64','#57a3a2','#dfbd75','#7384b8','#d06e78','#ccd1c9','#56705e'];
function makeTraffic(){const type=Math.random()<.42?'truck':'car';const model=buildCar(type,trafficColors[Math.floor(Math.random()*trafficColors.length)]);model.scale.setScalar(type==='truck'?.9:.88);const group=new THREE.Group();group.add(model);scene.add(group);return {group,model,type,z:-75,x:0,speed:14+Math.random()*8,lane:0,active:false,changeAt:Math.random()*5+4,hit:false}}
for(let i=0;i<9;i++)traffic.push(makeTraffic());

let state='garage',distance=0,score=0,combo=1,nearMissStreak=0,elapsed=0,playerX=0,steer=0,impact=0,lastCollision=-10,collisions=[],speed=26,spawnTimer=1.4,lastTouch={left:0,right:0},tapPointer=null;
const settings={sensitivity:1,music:true,sfx:true};
const audio={ctx:null,analyser:null,gain:null,source:null,element:null,playing:false,track:0,tracks:[{title:'GOLDEN HOUR',artist:'ROADBOUND RADIO',kind:'synth'},{title:'OPEN COUNTRY',artist:'ROADBOUND RADIO',kind:'synth'},{title:'AFTERGLOW DRIVE',artist:'ROADBOUND RADIO',kind:'synth'}],bins:null,beat:0,step:0,nextAt:0};
function ensureAudio(){if(!audio.ctx){audio.ctx=new AudioContext();audio.analyser=audio.ctx.createAnalyser();audio.analyser.fftSize=256;audio.analyser.smoothingTimeConstant=.82;audio.gain=audio.ctx.createGain();audio.gain.gain.value=.36;audio.gain.connect(audio.analyser);audio.analyser.connect(audio.ctx.destination);audio.bins=new Uint8Array(audio.analyser.frequencyBinCount)}if(audio.ctx.state==='suspended')audio.ctx.resume()}
const scales=[[0,3,5,7,10,12,10,7],[0,2,5,7,9,12,9,7],[0,4,7,9,11,14,11,9]];
function note(freq,dur,vol,wave='sine',when=audio.ctx.currentTime){const o=audio.ctx.createOscillator(),g=audio.ctx.createGain();o.type=wave;o.frequency.setValueAtTime(freq,when);g.gain.setValueAtTime(.0001,when);g.gain.exponentialRampToValueAtTime(vol,when+.035);g.gain.exponentialRampToValueAtTime(.0001,when+dur);o.connect(g);g.connect(audio.gain);o.start(when);o.stop(when+dur+.04)}
function playSynth(){ensureAudio();audio.playing=true;audio.nextAt=audio.ctx.currentTime+.05;audio.step=0;audio.source=null;syncAudioUI()}
function scheduleMusic(){if(!audio.playing||!audio.ctx||audio.element)return;const now=audio.ctx.currentTime;const scale=scales[audio.track%scales.length];while(audio.nextAt<now+0.35){const t=audio.nextAt,k=audio.step%8,root=audio.track===1?196:audio.track===2?220:174;note(root*Math.pow(2,scale[k]/12),.65,.042,'triangle',t);if(k%2===0)note(root*.5,.85,.075,'sine',t);if(k===0||k===4){note(70,.12,.08,'sine',t);audio.beat=1}if(k%2===1)note(root*Math.pow(2,(scale[k]+12)/12),.34,.018,'sine',t);audio.nextAt+=.38;audio.step++}}
function setTrack(i){audio.track=(i+audio.tracks.length)%audio.tracks.length;const t=audio.tracks[audio.track];$('#song-title').textContent=t.title;$('#song-subtitle').textContent=t.artist;$('#mini-song').textContent=t.title;$('#radio-title').textContent=t.title;$('#radio-source').textContent=t.artist;renderPlaylist();if(audio.playing&&t.kind==='synth')playSynth();}
function toggleAudio(){if(!settings.music)return;ensureAudio();if(audio.element){if(audio.element.paused){audio.element.play();audio.playing=true}else{audio.element.pause();audio.playing=false}}else if(audio.playing){audio.playing=false}else playSynth();syncAudioUI()}
function syncAudioUI(){const icon=audio.playing?'Ⅱ':'▶';$('#play-radio').textContent=icon;$('#sound-toggle').style.opacity=settings.music?'1':'.45'}
function audioLevel(){if(!audio.analyser)return 0;audio.analyser.getByteFrequencyData(audio.bins);let sum=0;for(let i=0;i<12;i++)sum+=audio.bins[i];return sum/(12*255)}

function centerAt(z){return 1.15*Math.sin((distance-z)*.006)+.45*Math.sin((distance-z)*.017)}
function resetTraffic(t,initial=false){t.z=initial?-40-Math.random()*175:-105-Math.random()*72;t.lane=[-4,-1.35,1.35,4][Math.floor(Math.random()*4)];t.x=t.lane;t.speed=13+Math.random()*11+Math.min(distance*.004,8);t.changeAt=3+Math.random()*6;t.active=true;t.hit=false;t.model.rotation.y=0;t.group.visible=true}
function spawnTraffic(){const inactive=traffic.find(t=>!t.active);if(inactive){resetTraffic(inactive);}}
function makeCrashSound(){if(!settings.sfx||!audio.ctx)return;const t=audio.ctx.currentTime;note(83,.18,.12,'triangle',t);note(56,.24,.1,'sawtooth',t+.03)}
function showNear(){const n=$('#near-miss');n.classList.add('show');setTimeout(()=>n.classList.remove('show'),900)}
function hitTraffic(t){if(t.hit)return;t.hit=true;impact=1;playerX+=playerX<t.x?-.5:.5;t.x+=t.x>playerX?.48:-.48;t.speed*=.65;collisions.push(elapsed);collisions=collisions.filter(x=>elapsed-x<4.5);lastCollision=elapsed;$('#collision-flash').classList.add('hit');setTimeout(()=>$('#collision-flash').classList.remove('hit'),150);makeCrashSound();if(collisions.length>=3)endRun()}
function startRun(){state='playing';distance=score=elapsed=0;combo=1;nearMissStreak=0;playerX=0;steer=0;collisions=[];speed=25;spawnTimer=.8;traffic.forEach(t=>{t.active=false;t.group.visible=false});for(let i=0;i<4;i++)resetTraffic(traffic[i],true);$('#garage-screen').classList.add('hidden');$('#hud').classList.remove('hidden');$('#gameover-screen').classList.add('hidden');$('#pause-screen').classList.add('hidden');if(!audio.playing&&settings.music)toggleAudio();$('#touch-hint').style.opacity='1';setTimeout(()=>$('#touch-hint').style.opacity='0',3500)}
function endRun(){if(state!=='playing')return;state='over';$('#final-score').textContent=Math.floor(score).toLocaleString();$('#final-distance').textContent=(distance/1000).toFixed(1)+' km';$('#hud').classList.add('hidden');$('#gameover-screen').classList.remove('hidden')}
function pauseRun(){if(state!=='playing')return;state='paused';$('#pause-screen').classList.remove('hidden')}
function resumeRun(){state='playing';$('#pause-screen').classList.add('hidden')}

function setGarage(){state='garage';$('#hud').classList.add('hidden');$('#pause-screen').classList.add('hidden');$('#gameover-screen').classList.add('hidden');$('#garage-screen').classList.remove('hidden');$('#customize-panel').classList.add('hidden');$('#settings-panel').classList.add('hidden');$('#radio-panel').classList.add('hidden');}
function updateVehicleLabel(){$('#vehicle-name').textContent=cars[selected].name;rebuildPlayer()}
$('#prev-car').onclick=()=>{selected=(selected+1)%2;updateVehicleLabel()};$('#next-car').onclick=()=>{selected=(selected+1)%2;updateVehicleLabel()};$('#play-btn').onclick=startRun;$('#pause-btn').onclick=pauseRun;$('#resume-btn').onclick=resumeRun;$('#restart-btn').onclick=startRun;$('#quit-btn').onclick=setGarage;$('#garage-btn').onclick=setGarage;
$('#customize-btn').onclick=()=>$('#customize-panel').classList.remove('hidden');$('#settings-btn').onclick=()=>$('#settings-panel').classList.remove('hidden');$('#custom-done').onclick=()=>$('#customize-panel').classList.add('hidden');$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).classList.add('hidden'));
function renderSwatches(){const root=$('#swatches');root.innerHTML='';paintColors.forEach((c,i)=>{const b=document.createElement('button');b.className='swatch'+(paintIndex[selected]===i?' active':'');b.style.background=c;b.onclick=()=>{paintIndex[selected]=i;renderSwatches();rebuildPlayer()};root.append(b)})}renderSwatches();$$('.tab').forEach(b=>b.onclick=()=>{$$('.tab').forEach(x=>x.classList.toggle('active',x===b));$$('.tab-content').forEach(x=>x.classList.add('hidden'));$('#'+b.dataset.tab+'-content').classList.remove('hidden')});$$('[data-finish]').forEach(b=>b.onclick=()=>{$$('[data-finish]').forEach(x=>x.classList.toggle('active',x===b));finish=b.dataset.finish;rebuildPlayer()});$$('[data-wheel]').forEach(b=>b.onclick=()=>{$$('[data-wheel]').forEach(x=>x.classList.toggle('active',x===b));wheelStyle=b.dataset.wheel});$$('[data-skin]').forEach(b=>b.onclick=()=>{$$('[data-skin]').forEach(x=>x.classList.toggle('active',x===b));skin=b.dataset.skin});
$('#sensitivity').oninput=e=>settings.sensitivity=Number(e.target.value)/100;$('#music-toggle').onclick=e=>{settings.music=!settings.music;e.currentTarget.classList.toggle('active',settings.music);if(!settings.music){audio.playing=false;if(audio.element)audio.element.pause()}else if(state==='playing'&&!audio.playing)toggleAudio();syncAudioUI()};$('#sfx-toggle').onclick=e=>{settings.sfx=!settings.sfx;e.currentTarget.classList.toggle('active',settings.sfx)};
function openRadio(){if(state==='playing')pauseRun();$('#radio-panel').classList.remove('hidden')};$('#hud-radio').onclick=openRadio;$('#pause-radio').onclick=openRadio;$('#sound-toggle').onclick=toggleAudio;$('#play-radio').onclick=toggleAudio;$('#prev-song').onclick=()=>setTrack(audio.track-1);$('#next-song').onclick=()=>setTrack(audio.track+1);$('#add-track').onclick=()=>$('#audio-input').click();
function renderPlaylist(){const list=$('#playlist');list.innerHTML='';audio.tracks.forEach((t,i)=>{const row=document.createElement('div');row.className='track'+(i===audio.track?' active':'');row.innerHTML=`<div class="track-art">♫</div><div><b>${t.title}</b><small>${t.artist}</small></div><em>${i===audio.track&&audio.playing?'♫':'▶'}</em>`;row.onclick=()=>{if(t.kind==='file'){audio.track=i;const el=audio.element;if(el)el.play();audio.playing=true;syncAudioUI();setTrackUIOnly()}else{audio.element?.pause();audio.element=null;audio.track=i;playSynth();setTrack(i)}};list.append(row)})}
function setTrackUIOnly(){const t=audio.tracks[audio.track];$('#song-title').textContent=t.title;$('#song-subtitle').textContent=t.artist;$('#mini-song').textContent=t.title;$('#radio-title').textContent=t.title;$('#radio-source').textContent=t.artist;renderPlaylist()}
$('#audio-input').onchange=e=>{const files=[...e.target.files];if(!files.length)return;ensureAudio();files.forEach(file=>{const url=URL.createObjectURL(file);audio.tracks.push({title:file.name.replace(/\.[^.]+$/,''),artist:'YOUR LIBRARY',kind:'file',url})});audio.track=audio.tracks.length-files.length;audio.element?.pause();audio.element=new Audio(audio.tracks[audio.track].url);audio.element.loop=false;audio.element.crossOrigin='anonymous';audio.source=audio.ctx.createMediaElementSource(audio.element);audio.source.connect(audio.gain);audio.element.onended=()=>{if(audio.playing){audio.track=(audio.track+1)%audio.tracks.length;playSelectedTrack()}};audio.element.play();audio.playing=true;setTrackUIOnly();syncAudioUI();});
function playSelectedTrack(){const t=audio.tracks[audio.track];if(t.kind==='file'){audio.element?.pause();audio.element=new Audio(t.url);audio.source=audio.ctx.createMediaElementSource(audio.element);audio.source.connect(audio.gain);audio.element.onended=()=>{audio.track=(audio.track+1)%audio.tracks.length;playSelectedTrack()};audio.element.play();audio.playing=true}else{audio.element?.pause();audio.element=null;playSynth()}setTrackUIOnly()}
$('#radio-panel .panel-close').onclick=()=>{$('#radio-panel').classList.add('hidden');if(state==='paused')resumeRun()};

