function playSelectedTrack(){const t=audio.tracks[audio.track];if(t.kind==='file'){audio.element?.pause();audio.element=new Audio(t.url);audio.source=audio.ctx.createMediaElementSource(audio.element);audio.source.connect(audio.gain);audio.element.onended=()=>{audio.track=(audio.track+1)%audio.tracks.length;playSelectedTrack()};audio.element.play();audio.playing=true}else{audio.element?.pause();audio.element=null;playSynth()}setTrackUIOnly()}
$('#radio-panel .panel-close').onclick=()=>{$('#radio-panel').classList.add('hidden');if(state==='paused')resumeRun()};

